final class Session {
    weak var delegate: SessionDelegate?          // non-owning back edge (zeroing)
    private let channel: Channel
    init(addr: String) { channel = Channel(addr: addr) }
    deinit { channel.close() }                   // release at the last strong ref
}

var session: Session? = Session(addr: "tcp://db")   // strong owner
weak var watcher: Session? = session                // nil after release
session = nil                                       // ARC releases; deinit runs
